package net.officefloor.hq.app.rollup;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Objects;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.ClaimRepository;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.rate.RateRepository;
import net.officefloor.hq.app.setting.SettingRepository;
import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.hq.app.statement.Dues;
import net.officefloor.hq.app.statement.LateCharge;
import org.springframework.stereotype.Service;

/** Takes the sheet's figures, and records in the audit file how they moved over a change: a ROLLUP line per
 *  person whose figures (claimed, due-total, overdue-total) changed (a person new to the sheet counting as changed), in the order they were added,
 *  then a TOTALS line when the sheet's totals changed (its due-total and overdue-total leave out the single highest and
 *  single lowest person's figure when three or more people have one; n/a is no figure), then, when the sheet has an
 *  alert threshold, an ALERT line per person whose due-total went from at or below it (or none) to above it, in
 *  list order. A change that moves no figure records nothing. */
@Service
public class Rollups {

    private final PersonRepository people;
    private final ClaimRepository claims;
    private final RateRepository rates;
    private final SheetRepository sheets;
    private final SettingRepository settings;
    private final Audit audit;

    public Rollups(PersonRepository people, ClaimRepository claims, RateRepository rates, SheetRepository sheets,
            SettingRepository settings, Audit audit) {
        this.people = people;
        this.claims = claims;
        this.rates = rates;
        this.sheets = sheets;
        this.settings = settings;
        this.audit = audit;
    }

    /** The sheet's figures as they are now. */
    public Rollup take(String sheetId) {
        var today = sheets.today(sheetId);
        var floor = settings.floor(sheetId);
        BigDecimal cap = settings.cap(sheetId);
        LateCharge late = LateCharge.of(sheetId, settings, sheets, claims, people);
        List<Claim> all = claims.list(sheetId);
        Map<Long, Rollup.Figures> figures = new LinkedHashMap<>();
        BigDecimal claimedTotal = new BigDecimal("0.00");
        List<BigDecimal> dues = new ArrayList<>();
        List<BigDecimal> overdues = new ArrayList<>();
        for (Person p : people.list(sheetId)) {
            List<Claim> theirs = all.stream().filter(c -> c.personId() == p.id()).toList();
            // claimed: the amounts of their claims that count, leaving out corrections of another claim
            BigDecimal claimed = theirs.stream()
                    .filter(c -> Dues.counts(c, p.holds(), p.retiredFrom(), today) && c.corrects() == null)
                    .map(Claim::amount).reduce(new BigDecimal("0.00"), BigDecimal::add);
            BigDecimal due = Dues.capped(
                    Dues.total(sheetId, theirs, p.grades(), p.holds(), p.retiredFrom(), today, rates, floor, late), cap);
            // overdue-total: the dues (as shown, late charge included) of their overdue claims that count, skipping n/a
            BigDecimal overdue = theirs.stream()
                    .filter(c -> Dues.counts(c, p.holds(), p.retiredFrom(), today) && late.overdue(c))
                    .map(c -> Dues.shown(c, p.grades(), rates, floor, late)).filter(Objects::nonNull)
                    .reduce(new BigDecimal("0.00"), BigDecimal::add);
            claimedTotal = claimedTotal.add(claimed);
            overdues.add(overdue);
            if (due != null) {
                dues.add(due);
            }
            figures.put(p.id(), new Rollup.Figures(p.name(), shown(claimed), due != null ? shown(due) : "n/a",
                    shown(overdue)));
        }
        return new Rollup(figures, shown(claimedTotal), shown(trimmed(dues)), shown(trimmed(overdues)));
    }

    /** Record how the sheet's figures moved since `before`, as a change made by `user`. */
    public void record(String sheetId, String user, Rollup before) {
        Rollup after = take(sheetId);
        for (var e : after.people().entrySet()) {
            Rollup.Figures was = before.people().get(e.getKey());
            Rollup.Figures now = e.getValue();
            if (was == null || !Objects.equals(was.claimed(), now.claimed())
                    || !Objects.equals(was.dueTotal(), now.dueTotal())
                    || !Objects.equals(was.overdueTotal(), now.overdueTotal())) {
                audit.record("ROLLUP sheet=" + sheetId + " by=" + user + " person=" + now.name()
                        + " claimed=" + now.claimed() + " due-total=" + now.dueTotal() + " overdue-total=" + now.overdueTotal());
            }
        }
        if (!before.claimedTotal().equals(after.claimedTotal()) || !before.dueTotal().equals(after.dueTotal())
                || !before.overdueTotal().equals(after.overdueTotal())) {
            audit.record("TOTALS sheet=" + sheetId + " by=" + user + " claimed-total=" + after.claimedTotal()
                    + " due-total=" + after.dueTotal() + " overdue-total=" + after.overdueTotal());
        }
        BigDecimal threshold = settings.alertThreshold(sheetId);
        if (threshold != null) {
            for (var e : after.people().entrySet()) {
                Rollup.Figures was = before.people().get(e.getKey());
                Rollup.Figures now = e.getValue();
                if (!above(was != null ? was.dueTotal() : null, threshold) && above(now.dueTotal(), threshold)) {
                    audit.record("ALERT sheet=" + sheetId + " by=" + user + " name=" + now.name()
                            + " due-total=" + now.dueTotal());
                }
            }
        }
    }

    /** Whether a due-total as shown (n/a or none: no due-total) is above the threshold. */
    private static boolean above(String dueTotal, BigDecimal threshold) {
        return dueTotal != null && !"n/a".equals(dueTotal) && new BigDecimal(dueTotal).compareTo(threshold) > 0;
    }

    /** Per-person figures added up, leaving out the single highest and the single lowest when there are three or more. */
    private static BigDecimal trimmed(List<BigDecimal> figures) {
        List<BigDecimal> sorted = figures.stream().sorted().toList();
        if (sorted.size() >= 3) {
            sorted = sorted.subList(1, sorted.size() - 1);
        }
        return sorted.stream().reduce(new BigDecimal("0.00"), BigDecimal::add);
    }

    private static String shown(BigDecimal value) {
        return value.setScale(2, RoundingMode.HALF_EVEN).toPlainString();
    }
}
package net.officefloor.hq.app.person;

import java.time.LocalDate;
import java.util.List;

/** A person's holds, in the order they were put on: each runs from its from-date (null: from the beginning of time)
 *  to its to-date (null: open-ended), both included. */
public record Holds(List<Hold> history) {

    /** A hold from a from-date to a to-date (either null: unbounded on that side). */
    public record Hold(LocalDate from, LocalDate to) {
        boolean covers(LocalDate date) {
            return (from == null || !from.isAfter(date)) && (to == null || !to.isBefore(date));
        }
    }

    public static final Holds NONE = new Holds(List.of());

    /** Whether the person has any hold. */
    public boolean any() {
        return !history.isEmpty();
    }

    /** Whether a hold covers the date. */
    public boolean covers(LocalDate date) {
        return history.stream().anyMatch(h -> h.covers(date));
    }
}
package net.officefloor.hq.app.statement;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.List;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.ClaimStatus;
import net.officefloor.hq.app.person.Grades;
import net.officefloor.hq.app.person.Holds;
import net.officefloor.hq.app.rate.Rates;
import net.officefloor.hq.app.setting.DatedAmount;

/** Claim figures and due-totals, as the screen shows them. */
public final class Dues {
    private Dues() {
    }

    /** A claim's figure: the due fixed when it was settled, else the one its last statement bound it to, n/a
     *  included (an OPEN or PENDING one alike), else live: its amount times its person's rate in force on
     *  its date for their grade then, divided by 100, rounded to two decimals as the claim rounds (see Rounding); null
     *  (n/a) when no rate applies. The floor is not in it: it is applied last (see shown). */
    public static BigDecimal figure(Claim claim, Grades grades, Rates rates, Rounding rounding) {
        if (claim.settledDue() != null) {
            return claim.settledDue();
        }
        if (claim.stated()) {
            return claim.statedDue();
        }
        return live(claim, grades, rates, rounding);
    }

    /** A claim's due as its row shows it: the due fixed when it was settled, else the one its last statement bound
     *  it to as shown then (late charge and floor included; n/a included), else the greater of the floor in force on
     *  its date and its live figure with the late charge on it added (a correction, a negative amount, has no floor
     *  and no charge); null (n/a) when it has no figure. */
    public static BigDecimal shown(Claim claim, Grades grades, Rates rates, DatedAmount floor,
            LateCharge late) {
        if (claim.settledDue() != null) {
            return claim.settledDue();
        }
        if (claim.stated()) {
            return claim.statedDue();
        }
        BigDecimal figure = figure(claim, grades, rates, late.rounding());
        if (figure == null || claim.amount().signum() < 0) {
            return figure;
        }
        return figure.add(late.on(claim, figure)).max(floor.on(claim.date()));
    }

    /** A claim's live figure: its amount times its person's rate in force on its date for their grade then (of the
     *  rates that reach it: a forward-only rate only reaches claims added after it), divided by 100, rounded to two
     *  decimals as the claim rounds (see Rounding); null (n/a) when no rate applies. */
    public static BigDecimal live(Claim claim, Grades grades, Rates rates, Rounding rounding) {
        return rates.on(claim.sheetId(), grades.on(claim.date()), claim.date(), claim.id())
                .map(r -> claim.amount().multiply(r.pct()).divide(BigDecimal.valueOf(100), 2, rounding.of(claim)))
                .orElse(null);
    }

    /** Whether a claim counts toward its person's figures and every live total: an OPEN, PENDING or SETTLED one,
     *  except an OPEN one held itself or dated within one of its person's holds and not bound by a statement, an OPEN or PENDING one
     *  not bound by a statement once its person's retirement date is reached (see retiredOut), and one deferred on the
     *  sheet's today (see Claim.deferredOn). */
    public static boolean counts(Claim claim, Holds holds, LocalDate retiredFrom, LocalDate today) {
        return claim.status().counts() && !claim.deferredOn(today)
                && !(claim.status() == ClaimStatus.OPEN && !claim.stated() && (claim.held() || holds.covers(claim.date())))
                && !retiredOut(claim, retiredFrom, today);
    }

    /** Whether a claim leaves the live totals because its person is retired: the sheet's today is on or after their
     *  retirement date (null: not retired) and it is OPEN or PENDING and not bound by a statement. */
    private static boolean retiredOut(Claim claim, LocalDate retiredFrom, LocalDate today) {
        return retiredFrom != null && today != null && !today.isBefore(retiredFrom) && !claim.stated()
                && (claim.status() == ClaimStatus.OPEN || claim.status() == ClaimStatus.PENDING);
    }

    /** Whether a claim counts toward a period's due-totals: its status at the end of the period's last day (see
     *  ClaimLogRepository.statusesAt; null: it was added after) is OPEN, PENDING or SETTLED, and it is left out
     *  as the live rules leave it out: deferred on the sheet's today, or an OPEN one dated within one of its
     *  person's holds and not bound by a statement, or an OPEN or PENDING one of a retired person (see counts). */
    public static boolean countsAtEnd(Claim claim, ClaimStatus atEnd, Holds holds, LocalDate retiredFrom,
            LocalDate today) {
        return atEnd != null && atEnd.counts() && !claim.deferredOn(today)
                && !(claim.status() == ClaimStatus.OPEN && !claim.stated() && (claim.held() || holds.covers(claim.date())))
                && !retiredOut(claim, retiredFrom, today);
    }

    /** A person's due-total: the dues (as shown) of their claims that count added up, skipping n/a; null (n/a) when
     *  their grade today has no rate today, unless a claim that counts has a figure (settled, stated, or live at
     *  the grade in force on its date). */
    public static BigDecimal total(String sheetId, List<Claim> claims, Grades grades, Holds holds,
            LocalDate retiredFrom, LocalDate today, Rates rates, DatedAmount floor, LateCharge late) {
        List<Claim> counted = claims.stream().filter(c -> counts(c, holds, retiredFrom, today)).toList();
        List<BigDecimal> figures = counted.stream().map(c -> shown(c, grades, rates, floor, late))
                .filter(f -> f != null).toList();
        if (figures.isEmpty() && rates.on(sheetId, grades.on(today), today).isEmpty()) {
            return null;
        }
        return figures.stream().reduce(new BigDecimal("0.00"), BigDecimal::add);
    }

    /** A due-total at most the sheet's cap (null: none); n/a (null) is not capped. */
    public static BigDecimal capped(BigDecimal total, BigDecimal cap) {
        return total != null && cap != null ? total.min(cap) : total;
    }
}

